def sha256_of(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def load(name: str) -> bytes:
    """The original bytes of one vendored file; a blob that doesn't match its pinned hash is an error."""
    blob, want = FILES[name]
    data = zlib.decompress(base64.b64decode(blob))
    if sha256_of(data) != want:
        raise ValueError(f"vendored file {name} does not match its pinned sha256")
    return data


def bundle() -> bytes:
    """The one script the page loads: the terminal, then its add-ons, each ending in a newline and a semicolon."""
    order = ("xterm.js", "addon-fit.js", "addon-clipboard.js", "addon-web-links.js")
    return b"".join(load(n).rstrip() + b"\n;\n" for n in order)
